parameterdescription.para:
keyの長さを生成します。ED448の場合は常に57になります。 Example intret;

WC_RNGrng;
ed448_keykey;

wc_InitRng(&rng);
wc_ed448_init(&key);
ret=wc_ed448_make_key(&rng,57,&key);
if(ret!=0){
//errormakingkey
}

simplesect.para:
BAD_FUNC_ARGS 与えられたキーがNULLの場合に返されます。 Example intret;
bytepriv[]={initializewith57byteprivatekey};
bytepub[]={initializewiththecorrespondingpublickey};

ed448_keykey;
wc_ed448_init_key(&key);
wc_ed448_import_private_key(priv,sizeof(priv),pub,sizeof(pub),&key);
ret=wc_ed448_check_key(&key);
if(ret!=0){
//errorcheckingkey
}

BAD_FUNC_ARGS 与えられたキーがNULLの場合に返されます。 Example intkeySz;
ed448_keykey;
//initializekey,makekey
keySz=wc_ed448_size(&key);
if(keySz==0){
//errordeterminingkeysize
}

BAD_FUNC_ARG key引数がnullの場合は返します。 Example ed448_keykey;
wc_ed448_init(&key);

WC_RNGrng;
wc_InitRng(&rng);

wc_ed448_make_key(&rng,57,&key);//initialize57byteEd448key
intkey_size=wc_ed448_priv_size(&key);

BAD_FUNC_ARG key引数がnullの場合は返します。 Example ed448_keykey;
wc_ed448_init(&key);
WC_RNGrng;
wc_InitRng(&rng);

wc_ed448_make_key(&rng,57,&key);//initialize57byteEd448key
intkey_size=wc_ed448_pub_size(&key);

BAD_FUNC_ARG key引数がnullの場合は返します。 Example intsigSz;
ed448_keykey;
//initializekey,makekey

sigSz=wc_ed448_sig_size(&key);
if(sigSz==0){
//errordeterminingsigsize
}
